insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('rhythm-instruments-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Rhythm Instruments', 'A playful, repeatable activity for tactile exploration.', 8, '5–10 min', 'Pots, spoons, containers', 'Pots, wooden spoon, and a sealed container of dried rice (lid taped shut so it can''t be opened). Make music together. Rhythm production is both sensory and fine motor.', 'This supports the sensory processing that underlies calm, settled behaviour. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('spinning-rolling-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Spinning Rolling', 'A playful, repeatable activity for vestibular (balance) input.', 4, '3–5 min', 'None', 'Roll baby gently on the floor or spin slowly in arms. Vestibular input supports balance, posture, and regulation.', 'This supports the sensory processing that underlies calm, settled behaviour. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('atta-dough-play-m13_15', 'cognitive'::domain, 'm13_15'::age_band, 'Atta Dough Play', 'A playful, repeatable activity for tactile exploration.', 13, '10–15 min', 'Wheat flour, water', 'Knead some atta (wheat dough) together. Baby squeezes, pokes, and flattens. Atta dough is pure fine motor and tactile input.', 'Toddlers need a lot of sensory input, and providing it deliberately often reduces the seeking behaviour that looks like mischief. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('spoon-use-practice-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Spoon Use Practice', 'A playful, repeatable activity for self-feeding with a spoon.', 18, '15–20 min', 'Spoon, food', 'Encourage spoon use at every meal, however messy. Competence by 18 months is the target: not table manners, just the motor skill.', 'This builds genuine independence at an age when wanting to be independent is at its peak. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'IAP Infant and Young Child Feeding; AAP Toilet Training Guidance; IAP'),
  ('partial-dressing-help-m13_15', 'social_emotional'::domain, 'm13_15'::age_band, 'Partial Dressing Help', 'A playful, repeatable activity for beginning to dress.', 8, '5–10 min', 'Clothing', 'Ask baby to push their arm through a sleeve or lift a foot for a sock. Participation (however partial) builds independence.', 'Toddlers want to do things themselves, and channelling that into real self-care tasks works with the drive rather than against it. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'IAP Infant and Young Child Feeding; AAP Toilet Training Guidance; IAP'),
  ('running-practice-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Running Practice', 'A simple activity that builds early running.', 13, '10–15 min', 'Open safe space', 'Running at 16–18 months is stiff-legged but consistent. Give open safe space and let them run freely: don''t slow them down.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('walk-up-stairs-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Walk Up Stairs', 'A playful, repeatable activity for walking and dynamic balance.', 8, '5–10 min', 'Stairs with rail', 'Walk up stairs holding the rail, one hand held. Alternating feet on stairs typically appears around 2 years: step-together is fine now.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('kick-ball-aim-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Kick Ball Aim', 'A playful, repeatable activity for kicking and lower-body coordination.', 8, '5–10 min', 'Ball + two objects as posts', 'Set up a ''goal'' (two objects as posts) and encourage kicking the ball between them. Directed kicking requires motor planning.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('jump-off-step-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Jump Off Step', 'An everyday activity that develops walking and dynamic balance.', 4, '3–5 min', 'Low step or book', 'Standing close beside baby, ready to catch, encourage jumping off the bottom stair or a thick book with both feet. Landing with both feet = motor milestone.', 'At this age balance is still developing, and each attempt refines it a little further. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('ladder-slide-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Ladder / Slide', 'An everyday activity that develops climbing and stepping coordination.', 13, '10–15 min', 'Playground or safe climbing surface', 'At a playground or safe homemade version, stay within arm''s reach as baby climbs up and comes down a small slide. Height + movement = vestibular rich.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('pedal-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Pedal', 'An everyday activity that develops functional strength and carrying.', 13, '10–15 min', 'Ride-on toy or adapted cardboard box', 'A push-along ride-on (or cardboard box to sit in) builds leg strength and spatial navigation before a true pedalling bike.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('balance-beam-walking-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Balance Beam Walking', 'A playful, repeatable activity for walking and dynamic balance.', 8, '5–10 min', 'Masking tape', 'Make a ''beam'' with masking tape on the floor. Encourage walking along the line with arms out. Balance challenges in a safe context.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('carry-heavy-load-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Carry Heavy Load', 'An everyday activity that develops functional strength and carrying.', 8, '5–10 min', 'Small bag with books', 'Ask baby to carry a small bag with a few books inside across the room. Heavy carrying is regulating to the sensory system.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('drawing-lines-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Drawing Lines', 'An everyday activity that develops first mark-making.', 8, '5–10 min', 'Crayons and paper', 'Show drawing a horizontal line across paper and let baby try. Any deliberate directional mark is an achievement.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('unscrew-screw-lids-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Unscrew Screw Lids', 'A playful, repeatable activity for rotational hand control.', 8, '5–10 min', 'Containers with lids', 'Practice opening and closing containers with twist lids. Rotation movements are a distinct fine motor skill used in daily life.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('stacking-6-blocks-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Stacking 6+ Blocks', 'A playful, repeatable activity for stacking and controlled release.', 8, '5–10 min', 'Blocks or similar', '6-block tower requires spatial planning, grip calibration, and controlled release. Each additional block is harder than it looks.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('tear-paper-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Tear Paper', 'A simple activity that builds bilateral tearing.', 8, '5–10 min', 'Old paper', 'Provide magazines or old newspaper for tearing. Bilateral tearing requires both hands working in opposition: a coordination milestone.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('string-beads-m16_18', 'motor'::domain, 'm16_18'::age_band, 'String Beads', 'A simple activity that builds threading and hand-eye coordination.', 8, '5–10 min', 'Large beads + shoelace', 'Thread 5 large beads or pasta pieces onto a shoelace, with close, constant supervision: beads should never be left within reach when unsupervised. Requires visual targeting, bilateral coordination, and sustained attention.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('puzzle-m16_18', 'motor'::domain, 'm16_18'::age_band, 'Puzzle', 'An everyday activity that develops hand strength and early dexterity.', 8, '5–10 min', 'Simple puzzle', 'A simple inset puzzle builds visual discrimination, spatial rotation, and the tolerance for trial-and-error failure.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('20-50-word-vocabulary-m16_18', 'communication'::domain, 'm16_18'::age_band, '20–50 Word Vocabulary', 'A simple activity that builds first words and vocabulary.', null, 'Ongoing', 'None', 'By 18 months, 20–50 words (including approximations) is the developmental target. Under 10 words by 18 months warrants a paediatrician mention.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('two-word-combinations-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Two-Word Combinations', 'A simple activity that builds first words and vocabulary.', null, 'Ongoing', 'None', 'More doodh'', ''bye dada'', ''big ball.'' Two-word phrases by 18 months are a major milestone. Model them in all conversation.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('what-s-that-response-m16_18', 'communication'::domain, 'm16_18'::age_band, 'What''s That?'' Response', 'A simple activity that builds first words and vocabulary.', null, 'Ongoing', 'None', 'Baby will point at everything and say ''woh kya hai?'' or similar. Every time: name it, describe it in one sentence, wait.', 'Your toddler understands much more than they can say, and this closes that gap. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('story-telling-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Story Telling', 'A simple activity that builds early narrative and vocabulary.', 8, '5–10 min', 'None', 'Tell a simple 3-sentence story about something that happened today. Story structure (beginning, middle, end) is absorbed before it is produced.', 'Your toddler understands much more than they can say, and this closes that gap. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('animal-sounds-game-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Animal Sounds Game', 'An everyday activity that develops first words and vocabulary.', 4, '3–5 min', 'None', 'Kutte kya bolta hai? Bhow bhow!'' Sound-to-animal linking builds vocabulary through a different encoding channel.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('action-word-focus-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Action Word Focus', 'A simple activity that builds first words and vocabulary.', null, 'Ongoing', 'None', 'Focus on verbs this week: running, eating, sleeping, jumping. Action vocabulary is as important as noun vocabulary.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('reading-together-daily-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Reading Together Daily', 'An everyday activity that develops early narrative and vocabulary.', 8, '5–10 min', 'Board book', 'Same book, multiple days in a row. When baby anticipates a page, they are demonstrating memory, sequence, and language: simultaneously.', 'Your toddler understands much more than they can say, and this closes that gap. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('singing-along-m16_18', 'communication'::domain, 'm16_18'::age_band, 'Singing Along', 'An everyday activity that develops first words and vocabulary.', 8, '5–10 min', 'None', 'In familiar songs, pause on the last word of each line and wait. By 18 months many babies fill in the word: word retrieval practice.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('simple-pretend-cooking-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Simple Pretend Cooking', 'A playful, repeatable activity for imitation and early pretend play.', 13, '10–15 min', 'Pots, spoons, empty containers', 'Give baby pots, spoons, and empty containers. Let them ''cook.'' Pretend play now represents real sequences observed in daily life.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('sort-shape-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Sort Shape', 'A simple activity that builds early sorting and matching.', 8, '5–10 min', 'Household objects of two shapes', 'Sort objects into two groups by shape: round things here, flat things there. Demonstrate; don''t expect immediate success.', 'This builds early problem-solving at an age when persistence is short and everything is experimental. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('picture-to-object-match-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Picture-to-Object Match', 'An everyday activity that develops object permanence and searching.', 7, '5–8 min', 'Picture and matching real object', 'Show a picture of a cup, then ask baby to find the real cup. Picture-object correspondence is an abstract cognitive skill.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('order-completion-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Order Completion', 'A simple activity that builds early memory.', null, 'Ongoing', 'None', 'Begin a familiar routine and stop mid-way. Watch baby signal or try to complete it: sequence memory is confirming itself.', 'This builds early problem-solving at an age when persistence is short and everything is experimental. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('count-objects-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Count Objects', 'An everyday activity that develops number word awareness.', 7, '5–8 min', 'Small objects for counting', 'Place 1, then 2, then 3 objects in a line counting aloud as you do. One-to-one correspondence is being seeded; production comes later.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('problem-solving-unstick-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Problem Solving Unstick', 'An everyday activity that develops simple problem-solving.', 7, '5–8 min', 'Tape and toy', 'Tape a desirable toy lightly to a table or box. Watch how baby figures out removing the tape or pulling the object free.', 'Understanding at this stage is built through direct experience, repeated many times. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('emotion-coaching-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Emotion Coaching', 'An everyday activity that develops emotional vocabulary.', null, 'Ongoing', 'None', 'When emotions arise, sit close and name the emotion specifically: ''You''re angry. That felt unfair.'' Don''t fix: just name and stay.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('feelings-chart-introduction-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Feelings Chart Introduction', 'An everyday activity that develops emotional vocabulary.', 7, '5–8 min', 'Paper with drawn faces', 'Put a simple 4-face chart on the wall: happy, sad, angry, scared. ''How are you feeling today? Point to the face.'' No judgment.', 'Your toddler is discovering they are a separate person with their own wants, which is why this stage is intense. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('practice-goodbye-ritual-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Practice Goodbye Ritual', 'A playful, repeatable activity for separation tolerance.', 3, '2–3 min', 'None', 'Develop a 3-step goodbye sequence for separations. Consistent, brief, warm: never long and uncertain. Consistency reduces distress.', 'Your toddler is discovering they are a separate person with their own wants, which is why this stage is intense. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('cooperative-game-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Cooperative Game', 'A simple activity that builds first turn-taking.', 8, '5–10 min', 'Ball', 'Sit facing each other and roll a ball back and forth. Taking turns in a structured physical game is cooperative play emerging.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('show-empathy-books-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Show Empathy Books', 'An everyday activity that develops emotional expression and early social skills.', 7, '5–8 min', 'Picture book', 'When a character in a book is sad or scared, narrate: ''Woh dara hua hai. Tum kya sochte ho?'' Perspective-taking through story.', 'Your toddler is discovering they are a separate person with their own wants, which is why this stage is intense. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('household-helper-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Household Helper', 'A simple activity that builds wanting to contribute.', 8, '5–10 min', 'Household task', 'Let baby ''help'' wipe a surface, stir food, hand you objects. Social participation and competence are both being built.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('sensory-bin-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Sensory Bin', 'A playful, repeatable activity for tactile exploration.', 13, '10–15 min', 'Container + fill material', 'This month use a different fill each week: sand, water, dried beans, shredded paper. Sensory tolerance broadens with variety.', 'Messy, tactile play at this age builds tolerance that makes eating and dressing easier too. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('outdoor-barefoot-walking-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Outdoor Barefoot Walking', 'An everyday activity that develops tactile exploration.', 13, '10–15 min', 'None (outdoors)', 'Walking barefoot on grass, sand, or dirt provides proprioceptive richness that shoes remove. 10 minutes barefoot outdoors = rich input.', 'Toddlers need a lot of sensory input, and providing it deliberately often reduces the seeking behaviour that looks like mischief. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('or-dough-play-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'or Dough Play', 'An everyday activity that develops tactile exploration.', 13, '10–15 min', 'Clay or atta dough', 'Commercial clay or homemade atta dough. Squeezing, rolling, and flattening are pure fine motor with rich tactile feedback.', 'Toddlers need a lot of sensory input, and providing it deliberately often reduces the seeking behaviour that looks like mischief. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('sound-discrimination-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Sound Discrimination', 'A playful, repeatable activity for auditory processing.', 4, '3–5 min', 'Any sound-making object', 'Make the same sound loudly and quietly: the same instrument or voice. Can baby identify louder and quieter? Auditory discrimination.', 'This supports the sensory processing that underlies calm, settled behaviour. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('blanket-roll-burrito-m16_18', 'cognitive'::domain, 'm16_18'::age_band, 'Blanket Roll Burrito', 'A simple activity that builds vestibular (balance) input.', 4, '3–5 min', 'Blanket', 'Roll baby gently in a blanket: not tight. The whole-body deep pressure is calming for the nervous system and delights most toddlers.', 'Messy, tactile play at this age builds tolerance that makes eating and dressing easier too. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('spoon-fork-independence-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Spoon Fork Independence', 'A simple activity that builds self-feeding with a spoon.', 18, '15–20 min', 'Fork, spoon, food', 'Offer fork for stabbing soft foods. Fork + spoon both available. Child chooses: autonomy in eating builds a positive food relationship.', 'Skills like these take far longer when a toddler does them, and that time is the investment. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'IAP Infant and Young Child Feeding; AAP Toilet Training Guidance; IAP'),
  ('washing-hands-routine-m16_18', 'social_emotional'::domain, 'm16_18'::age_band, 'Washing Hands Routine', 'A playful, repeatable activity for hygiene routines.', 3, '2–3 min', 'Soap, water, towel', 'Demonstrate hand washing before every meal and after outdoors. By 18 months, with reminding and help, this is beginning to establish.', 'Skills like these take far longer when a toddler does them, and that time is the investment. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'IAP Infant and Young Child Feeding; AAP Toilet Training Guidance; IAP'),
  ('running-direction-changes-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Running Direction Changes', 'An everyday activity that develops early running.', 13, '10–15 min', 'Open space', 'Set up a simple course: run to the tree, run back. Direction change while running requires significant motor planning updates.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('jump-both-feet-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Jump Both Feet', 'A simple activity that builds early jumping.', 4, '3–5 min', 'None', 'From ground level, encourage jumping with both feet simultaneously leaving the ground. Landing on both feet = major gross motor milestone.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('up-down-stairs-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Up Down Stairs', 'A simple activity that builds climbing and stepping coordination.', 8, '5–10 min', 'Stairs', 'Practice both directions on stairs with one hand on rail. Safety and independence are both being built.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('kick-stationary-ball-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Kick Stationary Ball', 'A simple activity that builds kicking and lower-body coordination.', 4, '3–5 min', 'Ball', 'Place a ball on the ground and ask baby to kick it. A stationary kick before a rolling ball: motor precision building.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('one-foot-briefly-m19_21', 'motor'::domain, 'm19_21'::age_band, 'One Foot Briefly', 'A simple activity that builds standing balance.', 4, '3–5 min', 'None', 'Hold baby''s hand and ask them to lift one foot for 2 seconds. Brief one-foot balance appearing 18–24 months.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('climbing-frames-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Climbing Frames', 'A simple activity that builds climbing and stepping coordination.', 13, '10–15 min', 'Climbing frame or playground', 'On any safe climbing frame or jungle gym, stay close enough to spot and catch if needed. Climbing is the most efficient builder of strength, coordination, and risk assessment.', 'At this age balance is still developing, and each attempt refines it a little further. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('throwing-target-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Throwing Target', 'An everyday activity that develops early throwing and ball skills.', 8, '5–10 min', 'Container and soft balls', 'Set up a large container and throw soft balls into it from a metre away. Aimed throwing builds visual-motor coordination.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('ride-on-steer-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Ride-On Steer', 'An everyday activity that develops walking and dynamic balance.', 13, '10–15 min', 'Ride-on or push cart', 'Push-along ride-on with steerable wheels, or just steering a cart. Navigation and steering need practice just like walking did.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('draw-vertical-line-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Draw Vertical Line', 'An everyday activity that develops first mark-making.', 8, '5–10 min', 'Crayon and paper', 'Show drawing a line from top to bottom and let toddler try. Directional mark-making is the direct precursor to letter formation.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('copy-circle-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Copy Circle', 'An everyday activity that develops first mark-making.', 8, '5–10 min', 'Crayon and paper', 'Show drawing a circle slowly and let toddler try. Circle before straight lines: fine motor milestone at 24–27 months when it appears.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('stack-8-blocks-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Stack 8+ Blocks', 'A simple activity that builds stacking and controlled release.', 8, '5–10 min', 'Blocks', '8-block tower requires sequential spatial planning: each level must be stable before the next. The planning IS the developmental work.', 'Fine motor skill at this stage is built through play rather than practice, and this offers plenty of both. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('cut-child-scissors-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Cut Child Scissors', 'A playful, repeatable activity for bilateral tearing.', 8, '5–10 min', 'Child scissors and paper', 'Introduce child-safe scissors with a parent steadying the paper. Cutting requires bilateral coordination and sustained grip.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('peg-pegboard-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Peg Pegboard', 'A playful, repeatable activity for hand strength.', 8, '5–10 min', 'Pegboard (homemade: card with holes)', 'Press pegs into a pegboard. Requires visual targeting, push force calibration, and the release of placing.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('lace-large-holes-m19_21', 'motor'::domain, 'm19_21'::age_band, 'Lace Large Holes', 'A simple activity that builds threading and hand-eye coordination.', 8, '5–10 min', 'Cardboard with holes + shoelace', 'Lace a shoelace through large holes in cardboard. Pre-lacing builds the same hand movements as actual shoe-lacing later.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('50-100-word-vocabulary-m19_21', 'communication'::domain, 'm19_21'::age_band, '50–100 Word Vocabulary', 'A simple activity that builds first words and vocabulary.', null, 'Ongoing', 'None', '50+ words by 20 months is solid. Under 20 consistent words by 20 months is worth discussing with a paediatrician.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('three-word-phrases-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Three-Word Phrases', 'An everyday activity that develops first words and vocabulary.', null, 'Ongoing', 'None', 'More apple please'', ''Mama come here.'' Three-word combinations beginning to appear 19–24 months.', 'Your toddler understands much more than they can say, and this closes that gap. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('refer-self-name-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Refer Self Name', 'A playful, repeatable activity for first words and vocabulary.', null, 'Ongoing', 'None', 'Aryan do it!'' Using own name before ''I'' is developmentally normal and means self-concept is forming.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('ask-why-game-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Ask ''Why?'' Game', 'A simple activity that builds first words and understanding.', null, 'Ongoing', 'None', 'When toddler asks ''why'' (it starts!), answer simply and then ask ''why do you think?'' Turn every why into a conversation.', 'Your toddler understands much more than they can say, and this closes that gap. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('story-re-tell-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Story Re-tell', 'A simple activity that builds early narrative and vocabulary.', 8, '5–10 min', 'Familiar book', 'After reading a familiar book, close it and ask ''What happened?'' Listen for any sequence: even one event recalled is narrative memory.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('colour-naming-focus-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Colour Naming Focus', 'A simple activity that builds first words and vocabulary.', null, 'Ongoing', 'None', 'Introduce one colour per week. Label it consistently all week: ''The red cup. Your red shoes. Red tomatoes!'' One at a time works best.', 'First words appear in this window, and they appear faster in children who are talked with rather than talked at. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('2-step-instruction-i-m19_21', 'communication'::domain, 'm19_21'::age_band, '2-Step Instruction I', 'An everyday activity that develops following simple instructions.', 4, '3–5 min', 'Cup', 'Pick up the cup AND bring it to me.'' Two unrelated steps in sequence tests working memory as well as language.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('conversation-practice-m19_21', 'communication'::domain, 'm19_21'::age_band, 'Conversation Practice', 'An everyday activity that develops first words and understanding.', 8, '5–10 min', 'None', 'Ask open questions about recent experiences: ''What did you see at the park?'' Don''t correct answers: expand and continue.', 'Vocabulary at this age grows through repeated, everyday exchanges far more than through teaching. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ASHA Speech and Language Milestones; AIISH India language norms; IAP'),
  ('cause-effect-multi-step-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Cause-Effect Multi-Step', 'A simple activity that builds cause-and-effect reasoning.', 8, '5–10 min', 'Books, ball, ramp (board)', 'Stack 3 books then push: watch toddler''s face. Set up a ramp and roll a ball down. Multi-step cause-effect chains are interesting now.', 'Understanding at this stage is built through direct experience, repeated many times. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('animals-vs-food-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Animals vs Food', 'A playful, repeatable activity for early sorting and matching.', 8, '5–10 min', 'Pictures or toy sets', 'Use pictures or objects: sort animals from foods. Categorisation by function or type is a major cognitive leap.', 'Understanding at this stage is built through direct experience, repeated many times. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('sequence-3-events-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Sequence 3 Events', 'A simple activity that builds early problem-solving and matching.', 7, '5–8 min', 'None', 'After a routine, ask what comes next: ''We had bath. Then what? Then what?'' Three-event sequence recall is emerging.', 'Understanding at this stage is built through direct experience, repeated many times. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('puzzle-6-8-pieces-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Puzzle 6–8 Pieces', 'A simple activity that builds shape and spatial matching.', 8, '5–10 min', 'Simple puzzle', '6–8 piece puzzle requiring rotation and trial-and-error. The frustration tolerance needed here is as developmental as the spatial skill.', 'Understanding at this stage is built through direct experience, repeated many times. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('count-1-5-objects-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Count 1–5 Objects', 'A simple activity that builds number word awareness.', 7, '5–8 min', 'Small objects', 'Place 3 objects in a line and count them together: touch each as you count. One-to-one correspondence beginning to appear.', 'Understanding at this stage is built through direct experience, repeated many times. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('memory-card-match-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Memory Card Match', 'An everyday activity that develops early sorting and matching.', 8, '5–10 min', '8 cards in 4 matching pairs', '4 pairs of matching cards face-down. Turn over 2 at a time. Early working memory and concentration.', 'Toddlers learn by trying things and seeing what happens, and this gives them something worth investigating. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'Harvard Center on the Developing Child (Executive Function); Zero to Three; IAP'),
  ('emotion-management-practice-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Emotion Management Practice', 'An everyday activity that develops early emotional regulation.', 7, '5–8 min', 'None', 'Before a frustrating task, name the strategy: ''If this is hard, take a breath.'' Practice during calm so it is available during frustration.', 'Your toddler is discovering they are a separate person with their own wants, which is why this stage is intense. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('turn-taking-games-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Turn Taking Games', 'An everyday activity that develops first turn-taking.', 8, '5–10 min', 'Any game', 'Establish clear turn-taking in a simple game. ''Meri baari. Ab tumhari baari.'' Consistent language makes the rule learnable.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('empathy-practice-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Empathy Practice', 'An everyday activity that develops emotional expression and early social skills.', null, 'Ongoing', 'None', 'Point out someone who is sad or hurt. ''Woh roh raha hai. Use dard hua. Hum kya kar sakte hain?'' Empathy is taught through narration.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('pretend-play-social-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Pretend Play Social', 'A playful, repeatable activity for emotional expression and early social skills.', 13, '10–15 min', 'Dolls, cups, play food', 'Set up a tea party or cooking scenario with dolls. Taking roles in pretend play is social cognition and narrative combined.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('self-advocacy-seed-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Self-Advocacy Seed', 'A playful, repeatable activity for emotional vocabulary.', null, 'Ongoing', 'None', 'When toddler is upset, model the phrase: ''I don''t like that'' or ''Mujhe yeh pasand nahi.'' Give them words for their feelings.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('comfort-skill-building-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Comfort Skill Building', 'A simple activity that builds early emotional regulation.', 7, '5–8 min', 'Soft object', 'Introduce a simple self-comfort strategy in a calm moment: slow breathing, squeezing a soft object. Practice before it is needed.', 'Emotional skills at this age are learned by being helped through feelings, over and over. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'Zero to Three; CASEL Social-Emotional Framework; UNICEF Responsive Caregiving; IAP'),
  ('water-transfer-play-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Water Transfer Play', 'An everyday activity that develops water play and sensory regulation.', 18, '15–20 min', 'Two containers + cup + water', 'Two containers of water, a cup for transferring. Supervised water play for 15 min. Pouring, splashing, and measuring emerge naturally.', 'This supports the sensory processing that underlies calm, settled behaviour. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('atta-dough-shapes-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Atta Dough Shapes', 'An everyday activity that develops tactile exploration.', 13, '10–15 min', 'Playdough or atta dough', 'With an adult handing over and collecting the knife each time, roll, flatten, and cut atta dough with a blunt knife. Making shapes adds visual-motor control to the tactile input.', 'Messy, tactile play at this age builds tolerance that makes eating and dressing easier too. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('nature-scavenger-hunt-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Nature Scavenger Hunt', 'An everyday activity that develops tactile exploration.', 25, '20–30 min', 'Bag for collecting', 'Walk outside and collect one of each: a leaf, a stone, a stick, a feather. Touch and describe each one together.', 'Toddlers need a lot of sensory input, and providing it deliberately often reduces the seeking behaviour that looks like mischief. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('bubble-play-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Bubble Play', 'A simple activity that builds sensory exploration and tolerance.', 13, '10–15 min', 'Soap + water + wire loop', 'Blow bubbles and let toddler pop them. Tracking, reaching, timing, and the satisfying pop make this multi-sensory and motivating.', 'Messy, tactile play at this age builds tolerance that makes eating and dressing easier too. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('paint-hands-m19_21', 'cognitive'::domain, 'm19_21'::age_band, 'Paint Hands', 'A playful, repeatable activity for tolerating messy textures.', 13, '10–15 min', 'Paint (washable), paper', 'Finger painting (food-safe paint or safe craft paint). Each colour is introduced separately. Direct contact with material.', 'Toddlers need a lot of sensory input, and providing it deliberately often reduces the seeking behaviour that looks like mischief. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Sensory Integration; Ayres Sensory Integration framework; IAP'),
  ('dressing-participation-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Dressing Participation', 'A playful, repeatable activity for beginning to dress.', 8, '5–10 min', 'Clothing', 'Name each clothing item as it goes on. Ask toddler to help push arm through sleeve or lift foot for shoe. Participation builds independence.', 'Toddlers want to do things themselves, and channelling that into real self-care tasks works with the drive rather than against it. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'IAP Infant and Young Child Feeding; AAP Toilet Training Guidance; IAP'),
  ('teeth-brushing-ritual-m19_21', 'social_emotional'::domain, 'm19_21'::age_band, 'Teeth Brushing Ritual', 'An everyday activity that develops hygiene routines.', 3, '2–3 min', 'Toothbrush', 'Brush teeth together at the same time. Letting toddler hold and attempt the brush first builds cooperation with the hygiene routine.', 'This builds genuine independence at an age when wanting to be independent is at its peak. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'IAP Infant and Young Child Feeding; AAP Toilet Training Guidance; IAP'),
  ('running-obstacle-course-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Running Obstacle Course', 'A simple activity that builds early running.', 13, '10–15 min', 'Chairs, cushions, tape', 'Set up household obstacles to run around: chairs, cushions, a line of tape. Navigating while running requires real-time motor planning.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('over-line-i-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Over Line I', 'An everyday activity that develops early jumping.', 4, '3–5 min', 'Masking tape', 'Put a tape line on the floor. Jump over with both feet. Clearing an obstacle while jumping = significantly harder than jumping in place.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('walk-backward-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Walk Backward', 'A playful, repeatable activity for walking and dynamic balance.', 8, '5–10 min', 'None', 'Practice walking backward, first holding hands then free. Backward locomotion requires body-awareness and spatial recalibration.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('throw-catch-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Throw Catch', 'A simple activity that builds early throwing and ball skills.', 8, '5–10 min', 'Large soft ball', 'Roll a large ball back and forth, then graduate to low throwing and catching. Catching a rolling ball before a thrown one.', 'At this age balance is still developing, and each attempt refines it a little further. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('pedal-tricycle-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Pedal Tricycle', 'An everyday activity that develops walking and dynamic balance.', 13, '10–15 min', 'Tricycle or balance bike', 'Practice on a tricycle or balance bike. Pedalling requires reciprocal leg movement: the same pattern as walking but with sustained force.', 'Walking is new and still effortful, so this kind of practice is what turns a wobbly skill into an automatic one. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('gallop-forward-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Gallop Forward', 'A playful, repeatable activity for walking and dynamic balance.', 8, '5–10 min', 'None', 'Demonstrate a gallop (lead-foot, drag) and encourage copying. Galloping before skipping: the intermediate coordination step.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('step-alternating-stairs-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Step Alternating Stairs', 'A simple activity that builds walking and dynamic balance.', 8, '5–10 min', 'Stairs', 'Encourage alternating feet on the way up the stairs. May still need rail; alternating feet up is a 24–30 month milestone.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('pull-heavy-objects-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Pull Heavy Objects', 'A simple activity that builds functional strength and carrying.', 8, '5–10 min', 'Chair or bag with books', 'Encourage pushing a chair or pulling a loaded bag. Resistance exercise builds core strength and spatial navigation simultaneously.', 'Toddlers need to move a great deal, and this gives that energy somewhere useful to go while building balance and strength. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'WHO Physical Activity Guidelines (under 5); AAP Physical Activity; IAP'),
  ('drawing-horizontal-line-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Drawing Horizontal Line', 'A playful, repeatable activity for first mark-making.', 8, '5–10 min', 'Crayon and paper', 'Show a horizontal line (left to right) and ask child to copy. Directionality in drawing precedes directionality in writing.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('copy-drawing-circle-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Copy Drawing Circle', 'A playful, repeatable activity for first mark-making.', 8, '5–10 min', 'Crayon and paper', 'Demonstrate a circle slowly and let child try. Circle-copying typically appears 24–30 months: earlier than + or V shapes.', 'Fine motor skill at this stage is built through play rather than practice, and this offers plenty of both. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('snip-scissors-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Snip Scissors', 'A playful, repeatable activity for bilateral tearing.', 8, '5–10 min', 'Child scissors and paper', 'With an adult supervising closely, use child-safe scissors to snip fringe into paper strips. Each snip is a complete bilateral motor action.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Let your toddler lead where possible, and accept that it will be slower and messier than doing it yourself.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('from-jug-cup-m22_24', 'motor'::domain, 'm22_24'::age_band, 'from Jug Cup', 'A playful, repeatable activity for pouring and wrist control.', 8, '5–10 min', 'Small jug and cup, water', 'Pour water from a small jug into a cup. The control of flow is a daily self-care fine motor skill used for years.', 'Small hands need a great deal of repetition, and this builds the strength and control that self-feeding and dressing will require. Follow their interest rather than the instructions, and stop while they are still enjoying it.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP'),
  ('puzzle-i-m22_24', 'motor'::domain, 'm22_24'::age_band, 'Puzzle I', 'A playful, repeatable activity for hand strength and early dexterity.', 8, '5–10 min', 'Puzzle', '8–10 piece puzzle requiring rotation and spatial reasoning. Systematically trying each piece before accepting failure is the cognitive goal.', 'This is the age where hands become genuinely useful tools, and that happens through hundreds of small attempts. Expect them to want it again immediately, and again after that; repetition is how toddlers learn.', 'AOTA Fine Motor Development; AAP Developmental Milestones; IAP')
